# ===========================================================================
# Assembly and main
# ===========================================================================


def operations() -> list[Operation]:
    ops: list[Operation] = []
    for rel, content in NEW_BACKEND_FILES.items():
        ops.append(NewFile(BACKEND, rel, content))
    for rel, content in NEW_FRONTEND_FILES.items():
        ops.append(NewFile(FRONTEND, rel, content))
    for rel, (sentinel, base, content) in REPLACED_BACKEND.items():
        ops.append(FileReplace(BACKEND, rel, sentinel, base, content))
    for rel, (sentinel, base, content) in REPLACED_FRONTEND.items():
        ops.append(FileReplace(FRONTEND, rel, sentinel, base, content))
    return ops


def main() -> int:
    parser = argparse.ArgumentParser(description="Apply ARCH-38.")
    parser.add_argument(
        "--check", action="store_true", help="report what would change, write nothing"
    )
    args = parser.parse_args()

    print("ARCH-38 — Batch Ingestion & Universal Document Intelligence")
    print(f"backend:  {BACKEND}")
    print(f"frontend: {FRONTEND}")
    print()

    if not FRONTEND.is_dir():
        print(f"  FAIL  frontend directory not found at {FRONTEND}")
        return 1

    ops = operations()

    # Everything is planned before anything is written, so a refusal in the
    # last file leaves the tree exactly as it was.
    planned: list[Planned] = []
    for op in ops:
        try:
            planned.append(plan(op))
        except PatchError as exc:
            print(f"  FAIL  {exc}")
            return 1

    changing = [p for p in planned if p.data is not None]
    for p in planned:
        print(f"  {'OK  ' if p.data is None else 'WRITE'}  {p.relpath}: {p.message}")
    print()
    print(f"  {len(changing)} file(s) would change")

    if args.check:
        return 0
    if not changing:
        print("\n  Nothing to do. ARCH-38 is already applied.")
        return 0

    # Written with a rollback journal: a failure halfway restores what this run
    # has already written, so the tree is never left half-applied.
    journal: list[tuple[Path, Optional[bytes]]] = []
    try:
        for p in changing:
            assert p.data is not None
            journal.append((p.path, None if p.created else p.path.read_bytes()))
            p.path.parent.mkdir(parents=True, exist_ok=True)
            p.path.write_bytes(p.data)
    except OSError as exc:
        print(f"\n  FAIL  {exc}. Rolling back this run.")
        for path, previous in reversed(journal):
            if previous is None:
                path.unlink(missing_ok=True)
            else:
                path.write_bytes(previous)
        return 1

    print(f"\n  {len(changing)} file(s) written.")
    print("  Next: alembic upgrade head, then npm install, then")
    print("        python verify_arch38.py --db --mutate --build")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())